{
  "protocol": "focus-trace-v3-reader-response-v1",
  "reader_id": "reader_29_38_sol",
  "focus_ref": "29:38",
  "trace_kind": "reconstructed",
  "baseline_models": [
    {
      "model_id": "base_evaluative_capture",
      "confidence": "strong",
      "focus_anchor": "`تَبَيَّنَ`, `زَيَّنَ`, `أَعْمَالَهُمْ`, `فَصَدَّهُمْ`, and `مُسْتَبْصِرِينَ`.",
      "mechanism": "Evidence and inward discernment remain present, but purposeful deeds receive an attractive valuation that is converted into movement away from a traversable way. Misguidance therefore operates through salience and desire rather than necessarily through factual blindness.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r02",
          "branch_key": "root_000170/B004",
          "role": "Emergence into clarity supplies accessible evidence rather than hidden information."
        },
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Presenting something as beautiful supplies the evaluative overlay that redirects attraction."
        },
        {
          "occurrence_id": "29:38/r05",
          "branch_key": "root_000796/B004",
          "role": "Rebellious agency personifies the force exploiting the gap between discernment and conduct."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Purposive action locates the distortion in chosen conduct, not merely in passive appearances."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Turning or keeping someone away converts altered valuation into obstructed movement."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "A route meant to be traversed gives the diversion a directional target."
        },
        {
          "occurrence_id": "29:38/r10",
          "branch_key": "root_000121/B002",
          "role": "Inward discernment remains active, creating the verse's knowledge-action paradox."
        }
      ],
      "changed_reading": {
        "before": "Satan misled people because they failed to see the truth.",
        "after": "They could discern, yet an attractive appraisal of their own intentional conduct redirected them away from what they could see."
      }
    },
    {
      "model_id": "base_settlement_route_tension",
      "confidence": "medium",
      "focus_anchor": "`مَسَاكِنِهِمْ` set beside `عَنِ السَّبِيلِ`, with `الشَّيْطَان` as the intervening agent.",
      "mechanism": "The focus creates a spatial field in which habitation supplies stillness and felt security, the Satan-root supplies distance, and diversion prevents travel along a route. Settled comfort can thus become fixation rather than genuine orientation.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B001",
          "role": "Cessation of motion gives the dwellings an immobilizing spatial quality."
        },
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B004",
          "role": "A place toward which the self settles supplies the affective pull of familiar security."
        },
        {
          "occurrence_id": "29:38/r05",
          "branch_key": "root_000796/B001",
          "role": "Distance and severance make Satanic agency function as separation from the route."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Preventive diversion turns attachment into failed passage."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "The extended road supplies the movement pole opposed to settled fixation."
        }
      ],
      "changed_reading": {
        "before": "The dwellings merely identify where the destroyed peoples once lived.",
        "after": "The verse also stages a tension between reassuring settlement and the movement demanded by a way."
      }
    },
    {
      "model_id": "base_counter_display",
      "confidence": "strong",
      "focus_anchor": "The contrast between `تَبَيَّنَ لَكُم مِن مَسَاكِنِهِمْ` and `زَيَّنَ لَهُم ... أَعْمَالَهُمْ`.",
      "mechanism": "Two displays address two audiences at two times: deeds were made attractive to them, while their remaining dwellings now disclose something contrary to you. The settled residue becomes a counter-image that strips the former deeds of their ornament.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r02",
          "branch_key": "root_000170/B004",
          "role": "Present disclosure supplies the corrective visibility available to the later audience."
        },
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B002",
          "role": "The inhabited place becomes the durable medium through which the past is now read."
        },
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Former beautification supplies the deceptive display that the surviving site reverses."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Their intentional deeds are the object whose apparent beauty is retrospectively exposed."
        }
      ],
      "changed_reading": {
        "before": "The ayah simply reports ancient destruction and Satanic temptation.",
        "after": "It contrasts their beautified self-display with the later forensic display of their dwellings."
      }
    }
  ],
  "context_deltas": [
    {
      "model_id": "ctx_socialized_obstruction",
      "status": "revised",
      "confidence": "strong",
      "mechanism": "A rival way is advertised through following, falsely insured by a promise to bear liability, made attractive through communal affection, and finally enacted as obstruction of a public road. Satanic adornment can therefore operate as a social institution that recruits and then reproduces diversion.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Making conduct look good supplies the persuasive surface of the rival social route."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Intentional deeds supply the conduct through which the social mechanism is embodied."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Diversion supplies both the initial displacement and its eventual reproduction against others."
        },
        {
          "occurrence_id": "29:12/r04",
          "branch_key": "root_000175/B001",
          "role": "Going behind another supplies the recruitment act by which a rival guide acquires followers."
        },
        {
          "occurrence_id": "29:12/r05",
          "branch_key": "root_000672/B001",
          "role": "The offered road makes misdirection an explicitly competing itinerary."
        },
        {
          "occurrence_id": "29:12/r06",
          "branch_key": "root_000357/B004",
          "role": "Bearing as surety supplies a false guarantee that lowers the perceived cost of deviation."
        },
        {
          "occurrence_id": "29:25/r06",
          "branch_key": "root_001634/B001",
          "role": "Interpersonal affection supplies the emotional ornament holding the shared practice together."
        },
        {
          "occurrence_id": "29:25/r07",
          "branch_key": "root_000170/B003",
          "role": "A bond joining parties turns private preference into a relational structure."
        },
        {
          "occurrence_id": "29:29/r03",
          "branch_key": "root_001240/B023",
          "role": "Forcible interception of a road makes diverted conduct actively prevent other people's passage."
        },
        {
          "occurrence_id": "29:29/r04",
          "branch_key": "root_000672/B001",
          "role": "The repeated traversable way identifies the same directional arena in which obstruction is enacted."
        }
      ],
      "structural_cues": [
        "The path lexeme moves from an invitation to follow “our way” to an explicitly cut way and then to the focus's barred way.",
        "Plural speech, reciprocal affection, and public conduct align with the focus's collective pronouns."
      ],
      "reader_inference": "The packet supplies separate scenes of recruitment, promised indemnity, social affection, and route-cutting; I infer an arrow from attractive belonging to reproduced obstruction. A live alternative is that these are parallel examples without identifying human networks as Satan's operative channel.",
      "changed_reading": {
        "before": "Satan privately alters each person's perception of personal deeds.",
        "after": "Deception is socially brokered: a rival route is advertised, its risks are rhetorically transferred, belonging decorates it, and diverted agents become obstacles for others."
      }
    },
    {
      "model_id": "ctx_forensic_dwelling",
      "status": "strengthened",
      "confidence": "strong",
      "mechanism": "A deliberately retained sign, followed by people fixed motionless in their home, turns habitation into evidence through arrested movement. The focus's dwellings are consequently read as forensic residues, not neutral scenery.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r02",
          "branch_key": "root_000170/B004",
          "role": "Disclosure names the interpretive result produced by the surviving site."
        },
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B001",
          "role": "Stillness converts a former place of life into an arrested material trace."
        },
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B002",
          "role": "Habitation supplies the concrete location in which the trace remains readable."
        },
        {
          "occurrence_id": "29:35/r01",
          "branch_key": "root_000180/B002",
          "role": "Leaving an effect behind supplies the preservation process that makes later reading possible."
        },
        {
          "occurrence_id": "29:35/r02",
          "branch_key": "root_000074/B003",
          "role": "An outwardly recognizable mark assigns evidentiary function to the retained residue."
        },
        {
          "occurrence_id": "29:35/r03",
          "branch_key": "root_000170/B004",
          "role": "Manifest clarity directly anticipates the focus's disclosure from dwellings."
        },
        {
          "occurrence_id": "29:37/r06",
          "branch_key": "root_000222/B001",
          "role": "Bodies adhering to the ground and place supply the image of habitation abruptly immobilized."
        }
      ],
      "structural_cues": [
        "A “clear sign” is immediately followed by becoming fixed “in their home,” then by becoming clear “from their dwellings.”",
        "The repeated clarity-root and home vocabulary form a compressed evidentiary sequence across adjacent examples."
      ],
      "reader_inference": "The packet supplies a retained clear sign, people fixed in their home, and disclosure from dwellings; I infer that arrested habitation makes the site legible. Alternatively, the sign and the immobilized inhabitants belong to neighboring peoples and need not be physically identified with Aad's or Thamud's remains.",
      "changed_reading": {
        "before": "The audience can infer destruction from generic ruins.",
        "after": "The dwellings function as preserved case evidence: places once defined by settled life now display the arrest of that life and expose the deeds once beautified there."
      }
    },
    {
      "model_id": "ctx_culpable_collaboration",
      "status": "strengthened",
      "confidence": "strong",
      "mechanism": "Clear proofs are followed by arrogance, individualized seizure for sin, and self-directed wrong. Satanic beautification is thus compatible with retained agency: it recruits pride and bad self-placement rather than coercively erasing responsibility.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Attractive presentation supplies the inducement without itself requiring compulsion."
        },
        {
          "occurrence_id": "29:38/r10",
          "branch_key": "root_000121/B002",
          "role": "Inward discernment preserves the cognitive capacity on which responsibility can attach."
        },
        {
          "occurrence_id": "29:39/r02",
          "branch_key": "root_000170/B004",
          "role": "Manifest proofs confirm that the neighboring resistance also occurs under evidentiary clarity."
        },
        {
          "occurrence_id": "29:39/r03",
          "branch_key": "root_001281/B006",
          "role": "Self-exalting greatness supplies the volitional posture that converts evidence into resistance."
        },
        {
          "occurrence_id": "29:40/r03",
          "branch_key": "root_000521/B001",
          "role": "Personal fault supplies the individualized basis on which consequences are assigned."
        },
        {
          "occurrence_id": "29:40/r12",
          "branch_key": "root_000967/B008",
          "role": "Withholding what is due supplies the moral deprivation turned back upon the actors."
        },
        {
          "occurrence_id": "29:40/r13",
          "branch_key": "root_001533/B012",
          "role": "The actors' own selves identify the recipient of the damage they enact."
        }
      ],
      "structural_cues": [
        "The focus is followed immediately by another group receiving clear proofs yet acting arrogantly.",
        "The catalog closes with “each” matched to fault and with the reversal from divine wrong to self-wrong."
      ],
      "reader_inference": "The packet supplies clarity, arrogance, individual fault, and self-wronging; I infer that preserved insight intensifies rather than cancels agency. A live alternative is that `مُسْتَبْصِرِينَ` denotes worldly competence rather than acknowledged moral truth.",
      "changed_reading": {
        "before": "The ancient peoples appear chiefly as victims of an external deceiver.",
        "after": "The external beautifier catalyzes a culpable collaboration in which perceptive actors exalt and injure themselves."
      }
    },
    {
      "model_id": "ctx_weak_shelter",
      "status": "revised",
      "confidence": "medium",
      "mechanism": "The spider-house analogy recasts decorated deeds and comforting settlements as a manufactured support system: intricate enough to feel inhabitable, yet unable to bear decisive pressure. False patronage offers psychological settlement without structural security.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B004",
          "role": "A place to which the self becomes calm supplies the felt security of the deceptive structure."
        },
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Beautification explains why a structurally poor refuge can remain affectively convincing."
        },
        {
          "occurrence_id": "29:41/r05",
          "branch_key": "root_001684/B004",
          "role": "Affiliative support supplies the protective relation that the constructed shelter is meant to embody."
        },
        {
          "occurrence_id": "29:41/r06",
          "branch_key": "root_001054/B001",
          "role": "A weaving creature supplies the image of a support architecture produced through repeated activity."
        },
        {
          "occurrence_id": "29:41/r07",
          "branch_key": "root_000166/B001",
          "role": "A sheltering home makes the analogy directly answer the focus's dwelling field."
        },
        {
          "occurrence_id": "29:41/r08",
          "branch_key": "root_001687/B001",
          "role": "Loss of strength exposes the inability of the attractive support system to protect its occupants."
        }
      ],
      "structural_cues": [
        "The house analogy follows immediately after the destruction catalog containing the focus.",
        "The simile's “if they knew” echoes the focus's claim that its people possessed discernment."
      ],
      "reader_inference": "The packet supplies false protectors, a constructed house, and structural weakness; I apply that analogy backward to the focus's dwelling-and-deed pair. Alternatively, the simile may critique patronage alone rather than characterize the ancient dwellings themselves.",
      "changed_reading": {
        "before": "The dwellings are inert remains and the deeds are separate moral objects.",
        "after": "The deeds can be read as weaving a soothing but load-bearingly weak habitation of false security."
      }
    },
    {
      "model_id": "ctx_counter_practice",
      "status": "new",
      "confidence": "strong",
      "mechanism": "The focus's causal sequence has an inverse: beautified action culminates in being kept from the way, whereas recurrent worship, recollection, and attention actively restrain degrading action. Practice can recalibrate salience before attractive wrongdoing hardens into obstruction.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Attractive presentation supplies the value distortion that the counter-practice must interrupt."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Purposive action is the shared behavioral level on which both loops operate."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Preventive redirection supplies the negative endpoint against which ritual restraint is reversed."
        },
        {
          "occurrence_id": "29:45/r05",
          "branch_key": "root_000879/B003",
          "role": "Specified worship supplies a repeated embodied practice rather than merely another proposition."
        },
        {
          "occurrence_id": "29:45/r06",
          "branch_key": "root_001560/B001",
          "role": "Active checking of conduct supplies the inverse barrier that blocks degrading acts."
        },
        {
          "occurrence_id": "29:45/r09",
          "branch_key": "root_000516/B003",
          "role": "Renewed recollection counters the attentional capture created by beautification."
        },
        {
          "occurrence_id": "29:45/r13",
          "branch_key": "root_000885/B001",
          "role": "Making or producing conduct keeps the counter-mechanism tied to what people actually enact."
        }
      ],
      "structural_cues": [
        "Both causal statements use a verb of prevention followed by `عَنْ`, but direct prevention toward opposite objects.",
        "The later sequence joins recitation, established practice, restraint, recollection, and what people produce."
      ],
      "reader_inference": "The packet supplies Satanic adornment followed by diversion and prayer followed by restraint; I infer an inverse behavioral control loop. A live alternative is that prayer's restraint is aspirational or partial rather than a guaranteed antidote to every instance of adornment.",
      "changed_reading": {
        "before": "The focus only diagnoses why perceptive people went astray.",
        "after": "It also becomes the negative half of a practice-based mechanism: disciplined remembrance can inhibit the deeds that would otherwise become a barrier."
      }
    },
    {
      "model_id": "ctx_inward_signs_known_denial",
      "status": "strengthened",
      "confidence": "strong",
      "mechanism": "Clear signs can be present within knowledgeable persons while active denial persists. The focus's `مُسْتَبْصِرِينَ` therefore need not indicate merely clever sinners; it can name cognition that has reached the interior without gaining obedient acknowledgment.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r02",
          "branch_key": "root_000170/B004",
          "role": "Disclosure establishes that the relevant evidence is genuinely available."
        },
        {
          "occurrence_id": "29:38/r10",
          "branch_key": "root_000121/B002",
          "role": "Discernment of the heart anchors the possibility of inwardly possessed yet ineffective insight."
        },
        {
          "occurrence_id": "29:49/r02",
          "branch_key": "root_000170/B004",
          "role": "Manifest signs repeat the focus's clarity at the level of revealed evidence."
        },
        {
          "occurrence_id": "29:49/r03",
          "branch_key": "root_000849/B001",
          "role": "The bodily chest supplies an internal location rather than merely an external display."
        },
        {
          "occurrence_id": "29:49/r05",
          "branch_key": "root_001040/B001",
          "role": "Cognitive disclosure identifies the recipients as possessors of knowledge."
        },
        {
          "occurrence_id": "29:49/r06",
          "branch_key": "root_000224/B001",
          "role": "Denial despite knowledge supplies the explicit mechanism by which inward evidence fails to govern allegiance."
        }
      ],
      "structural_cues": [
        "Clear signs move from ruined sites in the focus to the chests of knowledgeable recipients.",
        "The sequence directly combines clarity, inward location, knowledge, and denial."
      ],
      "reader_inference": "The packet supplies inward clear signs, knowledge, and denial with knowledge; I infer that the focus's insight may be genuine but behaviorally refused. Alternatively, the later recipients and the ancient peoples are distinct, and `مُسْتَبْصِرِينَ` may indicate practical acuity rather than inward recognition of the same signs.",
      "changed_reading": {
        "before": "`مُسْتَبْصِرِينَ` merely means that the people were intelligent or visually capable.",
        "after": "It can mark the more disturbing state in which truth is cognitively present yet actively denied at the level of allegiance."
      }
    },
    {
      "model_id": "ctx_deeds_become_environment",
      "status": "new",
      "confidence": "medium",
      "mechanism": "The attractive surface of deeds is reversed when punishment encloses the actors and they are told to experience what they used to do. Action is no longer merely an item in a record; it returns as an encompassing, embodied condition.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r04",
          "branch_key": "root_000660/B002",
          "role": "Displayed beauty supplies the initial sensory appraisal that later experience overturns."
        },
        {
          "occurrence_id": "29:38/r06",
          "branch_key": "root_001046/B001",
          "role": "Intentional deeds supply the material whose consequence becomes experiential."
        },
        {
          "occurrence_id": "29:54/r03",
          "branch_key": "root_000372/B006",
          "role": "Overmastering enclosure turns consequence into an environment with no external vantage point."
        },
        {
          "occurrence_id": "29:55/r02",
          "branch_key": "root_001088/B002",
          "role": "A covering that generalizes over its object supplies the all-around reach of the result."
        },
        {
          "occurrence_id": "29:55/r08",
          "branch_key": "root_000526/B002",
          "role": "Experiential tasting converts abstract appraisal into direct undergone knowledge."
        },
        {
          "occurrence_id": "29:55/r10",
          "branch_key": "root_001046/B001",
          "role": "The repeated deed-root explicitly ties the tasted condition back to prior purposive conduct."
        }
      ],
      "structural_cues": [
        "Enclosure is specified from above and below before the command to taste prior conduct.",
        "The same deed-root links the focus's beautified acts with the later object of embodied experience."
      ],
      "reader_inference": "The packet supplies surrounding punishment and the command to taste what was done; I infer an arrow by which accumulated action becomes lived environment. A live alternative is ordinary recompense metonymy in which punishment corresponds to deeds without becoming their materialized form.",
      "changed_reading": {
        "before": "Their deeds are falsely appraised objects belonging to the past.",
        "after": "The deeds build the condition they will inhabit and experience, revealing the eventual underside of their ornament."
      }
    },
    {
      "model_id": "ctx_rehousing",
      "status": "revised",
      "confidence": "medium",
      "mechanism": "Ruined settlements are answered by spacious earth and a promise to lodge right-acting people in elevated rooms. The spatial problem is not habitation itself but fixation in a deceptive refuge; release from it can culminate in a more durable, divinely assigned home.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B002",
          "role": "The dwelling supplies the failed habitation from which the relocation contrast begins."
        },
        {
          "occurrence_id": "29:38/r03",
          "branch_key": "root_000726/B004",
          "role": "Felt repose explains why leaving a familiar but deceptive setting can be difficult."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "A traversable way supplies the necessary movement between forms of habitation."
        },
        {
          "occurrence_id": "29:56/r04",
          "branch_key": "root_001647/B001",
          "role": "Open spatial breadth removes the claim that the present settlement is the only possible place."
        },
        {
          "occurrence_id": "29:58/r02",
          "branch_key": "root_001046/B001",
          "role": "Right action supplies the conduct associated with the replacement habitation."
        },
        {
          "occurrence_id": "29:58/r04",
          "branch_key": "root_000161/B001",
          "role": "Being assigned a lodging supplies the constructive answer to ruined or abandoned settlement."
        },
        {
          "occurrence_id": "29:58/r06",
          "branch_key": "root_001079/B002",
          "role": "An upper chamber supplies the stable destination that replaces false terrestrial security."
        }
      ],
      "structural_cues": [
        "The sequence moves from destroyed dwellings to wide earth and then to a promise of being lodged in rooms.",
        "The focus's deeds recur as right action immediately before the new habitation is assigned."
      ],
      "reader_inference": "The packet supplies ruined dwellings, spatial breadth, right action, and promised lodging; I infer a release-and-rehousing arc. Alternatively, the migration command and promised rooms may be independent exhortation rather than a retrospective comment on the focus's settlements.",
      "changed_reading": {
        "before": "The homes only preserve evidence of an ended civilization.",
        "after": "They also mark failed fixation within a larger relocation pattern: leave deceptive repose, traverse available space, and receive a sounder habitation."
      }
    },
    {
      "model_id": "ctx_correct_answer_wrong_direction",
      "status": "strengthened",
      "confidence": "strong",
      "mechanism": "People can verbally identify the creator and still be turned away and fail to exercise restraining reason. The focus's paradox is therefore directional rather than merely informational: a correct answer does not itself orient movement.",
      "activation_trace": [
        {
          "occurrence_id": "29:38/r10",
          "branch_key": "root_000121/B002",
          "role": "Inward discernment supplies cognitive capacity without guaranteeing navigation."
        },
        {
          "occurrence_id": "29:38/r07",
          "branch_key": "root_000848/B001",
          "role": "Being turned aside identifies failed orientation as the practical defect."
        },
        {
          "occurrence_id": "29:38/r08",
          "branch_key": "root_000672/B001",
          "role": "The route makes correct orientation a matter of movement rather than verbal description."
